    desc: "Кремниевая наночастица на тонкой золотой пленке работает как гибридный нанорезонатор. В отличие от чисто плазмонных, у него малы омические потери, высока температурная стабильность и есть сильный температурно-зависимый рамановский отклик. Это позволяет одновременно усиливать взаимодействие света с веществом и следить за молекулярными событиями с контролем температуры.",
